#!/usr/bin/env bash
set -euo pipefail

ICON_DIR="apps/desktop/src-tauri/icons"
ICON_PATH="$ICON_DIR/icon.png"
mkdir -p "$ICON_DIR"

# Neutral placeholder used until final TukuMail branding assets are supplied.
# Tauri requires an icon at compile time even when the product branding is intentionally provisional.
cat <<'B64' | base64 -d > "$ICON_PATH"

B64

echo "Generated provisional TukuMail desktop icon at $ICON_PATH"
